import{_ as s,o as r,c as a,a2 as t}from"./chunks/framework.ChIlRNAd.js";const p=JSON.parse(`{"title":"Vue d'ensemble","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/overview.md","filePath":"fr/guide/overview.md"}`),o={name:"fr/guide/overview.md"};function i(l,e,n,u,d,c){return r(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="vue-d-ensemble" tabindex="-1">Vue d&#39;ensemble <a class="header-anchor" href="#vue-d-ensemble" aria-label="Permalink to &quot;Vue d&#39;ensemble&quot;">​</a></h1><p>La <strong>Vue d&#39;ensemble</strong> (<code>/overview</code>, « Accueil » sur mobile) donne l&#39;état du compte Gmail actif et la prochaine action utile. C&#39;est la page d&#39;arrivée de Nid.</p><hr><h2 id="en-tete" tabindex="-1">En-tête <a class="header-anchor" href="#en-tete" aria-label="Permalink to &quot;En-tête&quot;">​</a></h2><p>« Bonjour {nom} », suivi de l&#39;adresse du compte et de l&#39;état de la sauvegarde (« Dernière sauvegarde il y a … » ou « Aucune sauvegarde pour l&#39;instant »).</p><hr><h2 id="indicateurs" tabindex="-1">Indicateurs <a class="header-anchor" href="#indicateurs" aria-label="Permalink to &quot;Indicateurs&quot;">​</a></h2><p>Quatre cartes cliquables (2×2 sur mobile) :</p><table tabindex="0"><thead><tr><th>Carte</th><th>Contenu</th><th>Mène à</th></tr></thead><tbody><tr><td><strong>Mails dans Gmail</strong></td><td>nombre de mails du compte, « N non lus »</td><td><a href="./mails.html">Mails</a></td></tr><tr><td><strong>Récupérable</strong></td><td>volume total des expéditeurs analysés, « N expéditeurs à nettoyer » (ou « Analyse des expéditeurs à lancer »)</td><td><a href="./cleanup.html">Nettoyage</a></td></tr><tr><td><strong>Sauvegarde NAS</strong></td><td>part des mails Gmail déjà archivés (en %), nombre de mails archivés, et le volume économisé par la déduplication des pièces jointes</td><td><a href="./archives.html">Archives</a></td></tr><tr><td><strong>Règles actives</strong></td><td>nombre de règles actives, « N mails traités ces 30 derniers jours »</td><td><a href="./rules.html">Règles &amp; libellés</a></td></tr></tbody></table><hr><h2 id="mails-recus-—-30-derniers-jours" tabindex="-1">Mails reçus — 30 derniers jours <a class="header-anchor" href="#mails-recus-—-30-derniers-jours" aria-label="Permalink to &quot;Mails reçus — 30 derniers jours&quot;">​</a></h2><p>Une barre par jour, d&#39;après les archives (date de réception des mails sauvegardés) : le graphique est fidèle quand la sauvegarde automatique est active. Les mêmes chiffres sont lus par les lecteurs d&#39;écran sous forme de tableau. <strong>Tout voir</strong> ouvre <a href="./archives.html">Archives</a>.</p><hr><h2 id="quand-arrivent-vos-mails" tabindex="-1">Quand arrivent vos mails <a class="header-anchor" href="#quand-arrivent-vos-mails" aria-label="Permalink to &quot;Quand arrivent vos mails&quot;">​</a></h2><p>Une grille jour × heure : plus la case est foncée, plus vous recevez de mails à ce créneau. Elle compte <strong>toutes vos archives</strong> (pas seulement 30 jours), à l&#39;heure locale de votre navigateur, et donne le créneau le plus chargé en toutes lettres (« Pic : lun. à 09 h »). Les lecteurs d&#39;écran lisent la grille sous forme de tableau. Aussi affichée pour les comptes IMAP.</p><hr><h2 id="inbox-zero" tabindex="-1">Inbox zero <a class="header-anchor" href="#inbox-zero" aria-label="Permalink to &quot;Inbox zero&quot;">​</a></h2><p>Comptes Gmail : le nombre de mails dans la boîte de réception (et de non lus), la série de jours consécutifs à zéro et votre record, puis l&#39;évolution sur 30 jours (le plus bas de chaque jour). Nid relève la boîte toutes les 6 heures : l&#39;historique se remplit au fil des jours.</p><hr><h2 id="top-encombreurs" tabindex="-1">Top encombreurs <a class="header-anchor" href="#top-encombreurs" aria-label="Permalink to &quot;Top encombreurs&quot;">​</a></h2><p>Les expéditeurs qui vous envoient le plus de mails, avec « N mails · taille ». <strong>Tout voir</strong> ouvre <a href="./cleanup.html">Nettoyage</a>.</p><hr><h2 id="suggestions" tabindex="-1">Suggestions <a class="header-anchor" href="#suggestions" aria-label="Permalink to &quot;Suggestions&quot;">​</a></h2><p>Nid repère des expéditeurs à traiter, par exemple :</p><ul><li>« {expéditeur} : N mails jamais lus (taille). »</li><li>« {expéditeur} occupe {taille} avec N mails. »</li><li>« {expéditeur} vous a envoyé N mails que vous lisez peu. »</li></ul><p>Chaque suggestion propose :</p><ul><li><strong>Se désabonner et nettoyer</strong> — même action que dans <a href="./cleanup.html#se-desabonner-et-nettoyer">Nettoyage</a> (désactivé si l&#39;expéditeur ne propose pas de désabonnement automatique) ; la progression s&#39;affiche sur la suggestion, qui disparaît une fois l&#39;action terminée ;</li><li><strong>Toujours faire ça</strong> — ouvre le formulaire de <a href="./rules.html#creer-une-regle">règle</a> pré-rempli avec l&#39;expéditeur ;</li><li><strong>Ignorer</strong> — masque la suggestion.</li></ul><hr><h2 id="plus-gros-mails-et-plus-grosses-pieces-jointes" tabindex="-1">Plus gros mails et plus grosses pièces jointes <a class="header-anchor" href="#plus-gros-mails-et-plus-grosses-pieces-jointes" aria-label="Permalink to &quot;Plus gros mails et plus grosses pièces jointes&quot;">​</a></h2><p>Les 5 mails archivés les plus lourds (objet, expéditeur, taille) et les 5 pièces jointes les plus lourdes (nom, objet du mail, taille). <strong>Tout voir</strong> ouvre <a href="./archives.html">Archives</a> ou <a href="./attachments.html">Pièces jointes</a>, triées par taille.</p><hr><h2 id="jobs-en-cours" tabindex="-1">Jobs en cours <a class="header-anchor" href="#jobs-en-cours" aria-label="Permalink to &quot;Jobs en cours&quot;">​</a></h2><p>Les tâches en cours d&#39;exécution, avec leur progression. <strong>Tout voir</strong> ouvre <a href="./activity.html">Activité</a>.</p>',33)])])}const m=s(o,[["render",i]]);export{p as __pageData,m as default};
